<?php
require_once __DIR__ . '/../config/Database.php';

/**
 * DigitalPrescription - A quotation/digital prescription generated by a pharmacist.
 * Contains items referencing MasterMedicine.
 */
class DigitalPrescription
{
    private int $digitalPrescriptionId;
    private int $reservationId;
    private int $pharmacistId;
    private float $totalAmount;
    private array $items;
    private string $createdAt;

    public function __construct(array $data = [])
    {
        $this->digitalPrescriptionId = (int)($data['digital_prescription_id'] ?? 0);
        $this->reservationId = (int)($data['reservation_id'] ?? 0);
        $this->pharmacistId = (int)($data['pharmacist_id'] ?? 0);
        $this->totalAmount = (float)($data['total_amount'] ?? 0.00);
        $this->items = $data['items'] ?? [];
        $this->createdAt = $data['created_at'] ?? '';
    }

    /**
     * Find a digital prescription by reservation ID.
     */
    public static function findByReservation(int $reservationId): ?self
    {
        $db = Database::getInstance()->getConnection();
        $stmt = $db->prepare(
            "SELECT * FROM digital_prescriptions WHERE reservation_id = :rid LIMIT 1"
        );
        $stmt->execute([':rid' => $reservationId]);
        $data = $stmt->fetch();

        if (!$data) return null;

        $dp = new self($data);
        $dp->items = $dp->getItems();
        return $dp;
    }

    /**
     * Find by ID.
     */
    public static function findById(int $id): ?self
    {
        $db = Database::getInstance()->getConnection();
        $stmt = $db->prepare("SELECT * FROM digital_prescriptions WHERE digital_prescription_id = :id LIMIT 1");
        $stmt->execute([':id' => $id]);
        $data = $stmt->fetch();

        if (!$data) return null;

        $dp = new self($data);
        $dp->items = $dp->getItems();
        return $dp;
    }

    /**
     * Calculate the total amount from all items.
     */
    public function calculateTotal(): float
    {
        $total = 0.0;
        foreach ($this->items as $item) {
            $total += (float)$item['quantity'] * (float)$item['unit_price'];
        }
        $this->totalAmount = $total;

        // Update in database
        $db = Database::getInstance()->getConnection();
        $stmt = $db->prepare(
            "UPDATE digital_prescriptions SET total_amount = :total WHERE digital_prescription_id = :id"
        );
        $stmt->execute([':total' => $total, ':id' => $this->digitalPrescriptionId]);

        return $total;
    }

    /**
     * Add an item to the digital prescription.
     */
    public function addItem(int $medicineId, int $quantity, float $price): bool
    {
        $db = Database::getInstance()->getConnection();
        $stmt = $db->prepare(
            "INSERT INTO digital_prescription_items (digital_prescription_id, medicine_id, quantity, unit_price)
             VALUES (:dpid, :mid, :qty, :price)"
        );
        $result = $stmt->execute([
            ':dpid'  => $this->digitalPrescriptionId,
            ':mid'   => $medicineId,
            ':qty'   => $quantity,
            ':price' => $price,
        ]);

        if ($result) {
            $this->items = $this->getItems();
            $this->calculateTotal();
        }

        return $result;
    }

    /**
     * Get all items in this digital prescription.
     */
    public function getItems(): array
    {
        $db = Database::getInstance()->getConnection();
        $stmt = $db->prepare(
            "SELECT dpi.*, m.brand_name, m.generic_name
             FROM digital_prescription_items dpi
             JOIN master_medicines m ON dpi.medicine_id = m.medicine_id
             WHERE dpi.digital_prescription_id = :dpid"
        );
        $stmt->execute([':dpid' => $this->digitalPrescriptionId]);
        return $stmt->fetchAll(PDO::FETCH_ASSOC);
    }

    // ── Getters ─────────────────────────────────
    public function getDigitalPrescriptionId(): int { return $this->digitalPrescriptionId; }
    public function getReservationId(): int { return $this->reservationId; }
    public function getTotalAmount(): float { return $this->totalAmount; }

    public function toArray(): array
    {
        return [
            'digital_prescription_id' => $this->digitalPrescriptionId,
            'reservation_id'          => $this->reservationId,
            'pharmacist_id'           => $this->pharmacistId,
            'total_amount'            => $this->totalAmount,
            'items'                   => $this->items,
            'created_at'              => $this->createdAt,
        ];
    }
}
